from taf.rfrl.l3_call.cell.classical_cell.classical_cell import ClassicalCell
from taf.rfrl.l3_call.logger.l3_call_logger import log_result, log_to_console


class ClassicalGsmCell(ClassicalCell):
    def __init__(self, cell_distname, bts_connection_alias, shared_spectrum):
        super(ClassicalGsmCell, self).__init__(cell_distname, bts_connection_alias, shared_spectrum)
        self._type = "GNCEL"

    def __str__(self):
        return "ClassicalGsmCell cell instance for {0} for cell type".format(self._type)

    def get_spectrum(self, cells_info, cell_specific_info):
        log_result("No need to calculate spectrum for GSM cell, returning zero")
        return [0, 0]

    def _get_cell_technology(self):
        log_result("Cell technology is not available for GSM cell")
        return None

    def _get_narrowband_iot_mode(self):
        log_result("IoT mode is not available for GSM cell")
        return None

    def _is_beamforming_activated(self):
        return False

    def _make_callable(self, delta):
        if not self._check_blocking_state(expected_state="Unblocked"):
            log_to_console("Making cell {} callable".format(self.distname))
            self._unblock_cell(timeout=90)
            self._check_blocking_state(expected_state="Unblocked")

    def _make_uncallable(self, delta):
        if not self._check_blocking_state(expected_state="Blocked"):
            log_to_console("Blocking cell {}".format(self.distname))
            self._block_cell(timeout=90)
            self._check_blocking_state(expected_state="Blocked")
